const phoneParagraph = document.querySelectorAll(".business-card p")[4];
assert.exists(phoneParagraph);
assert.match(phoneParagraph.textContent, /.+/);

const transparent = ['rgba(0, 0, 0, 0)', 'transparent'];
const htmlBackground = getComputedStyle(document.documentElement).backgroundColor;
const bodyBackground = getComputedStyle(document.body).backgroundColor;
const pageBackground = transparent.includes(htmlBackground) ? bodyBackground : htmlBackground;
assert.strictEqual(pageBackground, 'rgb(188, 143, 143)');

const elements = [...document.body.querySelectorAll('*')];
assert.isNotEmpty(elements);
for (const element of elements) {
  const fontFamily = getComputedStyle(element).fontFamily.replace(/["']/g, '');
  assert.match(fontFamily, /^Arial,\s*sans-serif$/i);
}

const paragraphs = [...document.querySelectorAll('p')];
assert.isNotEmpty(paragraphs);
for (const paragraph of paragraphs) {
  const { marginTop, marginBottom } = getComputedStyle(paragraph);
  assert.strictEqual(marginTop, '5px');
  assert.strictEqual(marginBottom, '5px');
}

const links = [...document.querySelectorAll('a')];
assert.isNotEmpty(links);
for (const link of links) {
  assert.strictEqual(getComputedStyle(link).textDecorationLine, 'none');
}
